import { describe, expect, it } from "vitest";
import fs from "fs";
import path from "path";

// WP-10: GGG metadata id -> app item. Generated by tools/build-cx-ids.ts.
const MAP_FILE = path.resolve(
  __dirname,
  "../../../public/data/poe-source/cx-ids.json",
);
const ITEMS_FILE = path.resolve(
  __dirname,
  "../../../public/data/en/items.ndjson",
);
const FIXTURE_IDS = path.resolve(
  __dirname,
  "../../fixtures/market/cx-ids-forbidden-rites.json",
);

interface CxIdsFile {
  source: string;
  generatedOn: string;
  ids: Record<string, { name: string; ns: "ITEM" | "GEM" }>;
}

function loadMap(): CxIdsFile {
  return JSON.parse(fs.readFileSync(MAP_FILE, "utf8")) as CxIdsFile;
}

function loadItemKeys(): Set<string> {
  const keys = new Set<string>();
  for (const line of fs.readFileSync(ITEMS_FILE, "utf8").split("\n")) {
    if (!line.trim()) continue;
    const item = JSON.parse(line) as { refName?: string; namespace: string };
    if (item.refName) keys.add(`${item.namespace}::${item.refName}`);
  }
  return keys;
}

const fixtureIds = JSON.parse(fs.readFileSync(FIXTURE_IDS, "utf8")) as string[];

describe("cx-ids.json", () => {
  it("records its source and generation date", () => {
    const map = loadMap();
    expect(map.source).toBe(
      "https://repoe-fork.github.io/poe2/base_items.json",
    );
    expect(map.generatedOn).toMatch(/^\d{4}-\d{2}-\d{2}$/);
  });

  it("the fixture holds 648 ids", () => {
    expect(fixtureIds).toHaveLength(648);
  });

  it("maps every traded Forbidden Rites id to an item in items.ndjson", () => {
    const map = loadMap();
    const items = loadItemKeys();
    const unmapped = fixtureIds.filter((id) => {
      const entry = map.ids[id];
      return !entry || !items.has(`${entry.ns}::${entry.name}`);
    });
    expect(unmapped).toEqual([]);
  });

  it("holds no [DNT] placeholder names", () => {
    const placeholders = Object.entries(loadMap().ids).filter(([, e]) =>
      e.name.startsWith("[DNT]"),
    );
    expect(placeholders).toEqual([]);
  });

  it("maps the Etcher by its id, not its icon name", () => {
    const map = loadMap();
    expect(map.ids["Metadata/Items/Currency/CurrencyMagicQuality"]).toEqual({
      name: "Arcanist's Etcher",
      ns: "ITEM",
    });
    expect(
      map.ids["Metadata/Items/Currency/CurrencyWeaponMagicQuality"],
    ).toBeUndefined();
  });

  it.each([
    ["Metadata/Items/Currency/CurrencyAddModToRare", "Exalted Orb"],
    ["Metadata/Items/Currency/CurrencyModValues", "Divine Orb"],
    ["Metadata/Items/Currency/CurrencyRerollRare", "Chaos Orb"],
  ])("%s is %s", (id, name) => {
    expect(loadMap().ids[id]).toEqual({ name, ns: "ITEM" });
  });
});
